settings.custom_css:
selector .ak-faq-left, selector .ak-faq-right { min-width: 0; }
selector .elementor-widget-text-editor p { margin: 0; }
selector .ak-mb { display: none; }
@media (max-width: 767px) { selector .ak-dk { display: none; } selector .ak-mb { display: inline; } }
/* título FAQ: desktop/laptop rojo + negro; mobile negro + rojo (XD) */
selector .ak-faq-title .ak-g { color: #905532; }
@media (max-width: 767px) { selector .ak-faq-title .elementor-heading-title { color: #100600 !important; } selector .ak-faq-title .ak-g { color: #905532; } }

selector .e-n-accordion { display: flex; flex-direction: column; gap: 14px; }
selector .e-n-accordion-item { background: #FFFFFF; border: 0; box-shadow: inset 0 0 0 1px #A1B5D3; border-radius: 15px; overflow: hidden; position: relative; transition: box-shadow .45s cubic-bezier(.22,.61,.36,1); }
selector .e-n-accordion-item[open] { box-shadow: inset 0 0 0 1px transparent; }
selector .ak-oro-text .elementor-heading-title, selector .ak-faq-title .ak-g { background-image: linear-gradient(#905532, #905532); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .e-n-accordion-item-title { display: flex !important; align-items: center; justify-content: space-between; gap: 16px;
  padding: 29px 25px 29px 64px !important; border: 0 !important; background: none !important; cursor: pointer; list-style: none; }
selector .e-n-accordion-item-title::-webkit-details-marker { display: none; }
selector .e-n-accordion-item-title-header { order: 1; flex: 1 1 auto; min-width: 0; justify-content: flex-start !important; text-align: left; }
selector .e-n-accordion-item-title-icon { order: 2; flex: 0 0 auto; margin-left: auto; }
selector .e-n-accordion-item-title-text { font: 400 18px/1.35 Inter, sans-serif !important; color: #100600 !important; text-align: left; }
selector .e-n-accordion-item-title-icon > span { width: 32px; height: 32px; border-radius: 50%; background-color: #F3F4F8; transition: background-color .45s cubic-bezier(.22,.61,.36,1);
  align-items: center; justify-content: center; }
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon > span { background-color: #905532; }
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-opened,
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-closed { display: none !important; }
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-opened,
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-closed { display: inline-flex !important; }
selector .e-n-accordion-item-title-icon i, selector .e-n-accordion-item-title-icon svg { font-size: 11px; width: 11px; height: 11px; color: #100600; fill: #100600; }
/* signo menos en blanco cuando la pregunta está abierta */
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon i,
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon svg,
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon svg path { color: #F3F5F7 !important; fill: #F3F5F7 !important; }
selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { border: 0 !important; background: none !important;
  padding: 0 64px 30px 64px !important; }
@media (max-width: 1366px) {
  selector .e-n-accordion-item-title { padding: 25px 20px 25px 40px !important; }
  selector .e-n-accordion-item-title-text { font-size: 16px !important; }
  selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { padding: 0 40px 26px 40px !important; }
}
@media (max-width: 767px) {
  selector .e-n-accordion { gap: 10px; }
  selector .e-n-accordion-item { border-radius: 12px; }
  selector .e-n-accordion-item-title { padding: 17px 14px 17px 18px !important; gap: 12px; }
  selector .e-n-accordion-item-title-text { font-size: 15px !important; line-height: 1.3 !important; }
  selector .e-n-accordion-item-title-icon > span { width: 28px; height: 28px; }
  selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { padding: 0 20px 22px 20px !important; }
}
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon i, selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon svg { color: #100600 !important; fill: #100600 !important; }
selector .e-n-accordion-item[open] > .e-con { animation: ak-faq-in .4s cubic-bezier(.22,.61,.36,1) both; }
@keyframes ak-acc-in { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { selector .e-n-accordion-item[open] > .e-con { animation: none; } }
/* desktop como el Figma: pregunta abierta a 20 px del borde, respuesta 24 px debajo con interlineado de 21 px */
@media (min-width: 1367px) {
  selector .e-n-accordion-item[open] > .e-n-accordion-item-title { transform: translateY(-8px); }
  selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { padding: 0 64px 16px 64px !important; }
  selector .elementor-widget-text-editor, selector .elementor-widget-text-editor p { line-height: 21px !important; }
}
/* transiciones del acordeón de preguntas (ver comentario arriba) */
selector .e-n-accordion-item::before { content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; background: #905532;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); opacity: 0; pointer-events: none; transition: opacity .45s cubic-bezier(.22,.61,.36,1); }
selector .e-n-accordion-item[open]::before { opacity: 1; }
selector .e-n-accordion-item > .e-n-accordion-item-title { transition: transform .45s cubic-bezier(.22,.61,.36,1); }
selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { position: relative; }
selector .e-n-accordion-item-title-icon i, selector .e-n-accordion-item-title-icon svg, selector .e-n-accordion-item-title-icon svg path { transition: color .45s cubic-bezier(.22,.61,.36,1), fill .45s cubic-bezier(.22,.61,.36,1); }
@keyframes ak-faq-in { from { opacity: 0; } to { opacity: 1; } }
@media (max-width: 1366px) {
  selector .e-n-accordion-item[open] > .e-con, selector .e-n-accordion-item[open] > [role="region"] { transform: translateY(-1px); }
}
@media (min-width: 1367px) {
  selector .e-n-accordion-item[open] > .e-con, selector .e-n-accordion-item[open] > [role="region"] { transform: translateY(-23px); }
}
@media (prefers-reduced-motion: reduce) {
  selector .e-n-accordion-item, selector .e-n-accordion-item::before, selector .e-n-accordion-item > .e-n-accordion-item-title,
  selector .e-n-accordion-item-title-icon > span, selector .e-n-accordion-item-title-icon i, selector .e-n-accordion-item-title-icon svg,
  selector .e-n-accordion-item-title-icon svg path { transition: none !important; }
}
